"""
FlexStack (Python) node for the signed interoperability matrix.

A complete ITS-S on the raw Ethernet link layer: CA basic service and DEN
service on BTP on a GeoNetworking router with security enabled
(``itsGnSecurity``). It signs with its own Authorization Ticket and trusts
only the Root CA and AA given on the command line: the ATs of the other nodes
are learned from the messages they send (signer ``certificate``), never
preloaded, so digest-signed CAMs verify only after the AT has been received.

* CAMs: generated by the CA basic service itself (TS 103 900 generation
  rules); the node drives a small circular trajectory so that the heading
  changes by more than 4 degrees every 100 ms and CAMs are sent at 10 Hz.
  The sign service includes the AT once per second and the digest otherwise
  (TS 103 097 clause 7.1.1).
* DENMs: one new event (AppDENM_trigger) per ``--denm-interval`` ms; DENMs are
  always signed with the certificate (TS 103 097 clause 7.1.2).

Every signing and verification outcome, and every CAM / DENM delivered to the
facilities, is written to stdout as one JSON line (../README.md, "Log format").
The node mirrors ``FlexStackBenchmarking/rust/src/interop_node.rs``.
"""

from __future__ import annotations

import argparse
import fcntl
import hashlib
import json
import math
import os
import random
import signal
import socket
import struct
import sys
import threading
import time

from flexstack.btp.router import Router as BTPRouter
from flexstack.facilities.ca_basic_service.ca_basic_service import CooperativeAwarenessBasicService
from flexstack.facilities.ca_basic_service.cam_transmission_management import VehicleData
from flexstack.facilities.decentralized_environmental_notification_service.den_protocol import DENMRequest
from flexstack.facilities.decentralized_environmental_notification_service.den_service import (
    DecentralizedEnvironmentalNotificationService,
)
from flexstack.geonet.gn_address import GNAddress, M, MID, ST
from flexstack.geonet.mib import MIB, GnIfType, GnSecurity
from flexstack.geonet.router import Router as GNRouter
from flexstack.linklayer.raw_link_layer import RawLinkLayer
from flexstack.security.certificate import Certificate, OwnCertificate
from flexstack.security.certificate_library import CertificateLibrary
from flexstack.security.ecdsa_backend import PythonECDSABackend
from flexstack.security.security_coder import SecurityCoder
from flexstack.security.sign_service import SignService
from flexstack.security.verify_service import VerifyService

CODER = SecurityCoder()
_LOG_LOCK = threading.Lock()
LOCATION = {"detectionZonesToEventPosition": [[{"pathPosition": {
    "deltaLatitude": 131072, "deltaLongitude": 131072, "deltaAltitude": 12800}}]]}


def log(node: str, event: str, **fields) -> None:
    """One JSON line on stdout."""
    record = {"t_ms": int(time.time() * 1000), "node": node, "event": event, **fields}
    with _LOG_LOCK:
        sys.stdout.write(json.dumps(record) + "\n")
        sys.stdout.flush()


def _hashedid8(certificate: dict) -> str:
    """HashedId8 of a P-256 certificate (TS 103 097 clause 6), hex."""
    return hashlib.sha256(CODER.encode_etsi_ts_103097_certificate(certificate)).digest()[-8:].hex()


def _signer(secured: bytes) -> tuple[str, str]:
    """(signer type, AT HashedId8) of an Ieee1609Dot2Data signed message."""
    try:
        signer = CODER.decode_etsi_ts_103097_data_signed(secured)["content"][1]["signer"]
    except Exception:  # pylint: disable=broad-except
        return "undecodable", ""
    if signer[0] == "digest":
        return "digest", signer[1].hex()
    if signer[0] == "certificate" and len(signer[1]) == 1:
        return "certificate", _hashedid8(signer[1][0])
    return signer[0], ""


def instrument_sign_service(node: str, sign_service: SignService) -> None:
    """Log every message the sign service signs (the GN router calls these)."""
    for method in ("sign_cam", "sign_denm", "sign_other"):
        original = getattr(sign_service, method)

        def wrapped(request, _original=original):
            confirm = _original(request)
            kind, at = _signer(confirm.sec_message)
            log(node, "tx", its_aid=int(request.its_aid), signer=kind, at=at, signed=True)
            return confirm

        setattr(sign_service, method, wrapped)


def verify_logger(node: str):
    """Verify observer of the GN router: logs the verdict of each received message."""
    def observe(message: bytes, confirm) -> None:
        kind, at = _signer(message)
        its_aid = confirm.its_aid
        if isinstance(its_aid, bytes):
            its_aid = int.from_bytes(its_aid, "big") if its_aid else -1
        log(node, "rx", its_aid=its_aid, signer=kind, at=at,
            report=confirm.report.name, verified=confirm.report.name == "SUCCESS")
    return observe


class CircleTrajectory:
    """TPV every 80 ms on a 10 m circle at 10 m/s (heading +4.6 deg per step)."""

    PERIOD_S, SPEED, RADIUS, EARTH_R = 0.08, 10.0, 10.0, 6_371_000.0

    def __init__(self, lat: float, lon: float) -> None:
        self.lat0, self.lon0 = lat, lon
        self.callbacks: list = []
        self.position = (lat, lon)
        self.stop = threading.Event()
        self.thread = threading.Thread(target=self._run, daemon=True)

    def _run(self) -> None:
        angle = 0.0
        while not self.stop.is_set():
            angle += self.SPEED * self.PERIOD_S / self.RADIUS
            north = self.RADIUS * math.sin(angle)
            east = self.RADIUS * (1 - math.cos(angle))
            lat = self.lat0 + math.degrees(north / self.EARTH_R)
            lon = self.lon0 + math.degrees(east / (self.EARTH_R * math.cos(math.radians(self.lat0))))
            self.position = (lat, lon)
            tpv = {"class": "TPV", "mode": 3, "time": time.strftime("%Y-%m-%dT%H:%M:%S.000Z", time.gmtime()),
                   "lat": lat, "lon": lon, "alt": 0.0, "speed": self.SPEED,
                   "track": math.degrees(angle + math.pi / 2) % 360, "epx": 1.0, "epy": 1.0, "eps": 0.1,
                   "climb": 0.0}
            for callback in self.callbacks:
                callback(tpv)
            self.stop.wait(self.PERIOD_S)


def interface_mac(iface: str) -> bytes:
    """MAC address of ``iface`` (SIOCGIFHWADDR; works in any network namespace)."""
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        info = fcntl.ioctl(sock.fileno(), 0x8927, struct.pack("256s", iface[:15].encode()))
    return info[18:24]


def build(args):  # pylint: disable=too-many-locals
    """The ITS-S of the node, not yet started."""
    certs = args.certs_dir
    read = lambda name: open(os.path.join(certs, name), "rb").read()  # noqa: E731
    backend = PythonECDSABackend()
    root = Certificate().decode(read(args.root + ".cert"), issuer=None)
    aa = Certificate().decode(read(args.aa + ".cert"), issuer=root)
    key_id = backend.import_signing_key(read(args.at + ".pem"))
    own = OwnCertificate(certificate=Certificate().decode(read(args.at + ".cert"), issuer=aa).certificate,
                         issuer=aa, key_id=key_id)
    sign_library = CertificateLibrary(ecdsa_backend=backend, root_certificates=[root],
                                      aa_certificates=[aa], at_certificates=[])
    sign_library.add_own_certificate(own)
    sign_service = SignService(backend, sign_library)
    instrument_sign_service(args.node, sign_service)
    verify_service = VerifyService(
        backend=backend, sign_service=sign_service,
        certificate_library=CertificateLibrary(ecdsa_backend=backend, root_certificates=[root],
                                               aa_certificates=[aa], at_certificates=[]))

    mac = interface_mac(args.iface)
    mib = MIB(itsGnIfType=GnIfType.ITS_G5, itsGnSecurity=GnSecurity.ENABLED,
              itsGnLocalGnAddr=GNAddress(m=M.GN_MULTICAST, st=ST.PASSENGER_CAR, mid=MID(mac)))
    gn = GNRouter(mib=mib, sign_service=sign_service, verify_service=verify_service)
    gn.set_verify_observer(verify_logger(args.node))
    trajectory = CircleTrajectory(args.lat, args.lon)
    trajectory.callbacks.append(gn.refresh_ego_position_vector)
    btp = BTPRouter(gn)
    gn.register_indication_callback(btp.btp_data_indication)

    vehicle = VehicleData(station_id=args.station_id, station_type=5, drive_direction="forward",
                          vehicle_length={"vehicleLengthValue": 1023,
                                          "vehicleLengthConfidenceIndication": "unavailable"},
                          vehicle_width=62)
    ca = CooperativeAwarenessBasicService(btp_router=btp, vehicle_data=vehicle)
    den = DecentralizedEnvironmentalNotificationService(btp, vehicle)
    btp.freeze_callbacks()
    ca.cam_reception_management.add_application_callback(
        lambda cam: log(args.node, "cam", decoded=True, station_id=cam["header"]["stationId"],
                        protocol_version=cam["header"]["protocolVersion"]))
    den.add_application_callback(
        lambda denm: log(args.node, "denm", decoded=True,
                         station_id=denm.denm["header"]["stationId"],
                         protocol_version=denm.denm["header"]["protocolVersion"]))
    if args.cam:
        trajectory.callbacks.append(ca.cam_transmission_management.location_service_callback)
    trajectory.callbacks.append(lambda tpv: den.set_ego_position(int(tpv["lat"] * 1e7),
                                                                 int(tpv["lon"] * 1e7)))
    link = RawLinkLayer(args.iface, mac, receive_callback=gn.gn_data_indicate)
    gn.link_layer = link
    if not gn.media_dependent_address_ok():
        raise SystemExit("itsGnLocalGnAddr MID must be the MAC address of the link layer")
    return trajectory, ca, den, link


def main() -> None:
    parser = argparse.ArgumentParser(description="FlexStack Python node, signed interop matrix")
    parser.add_argument("--node", default="python")
    parser.add_argument("--iface", default="eth0")
    parser.add_argument("--certs-dir", required=True)
    parser.add_argument("--root", default="root_ca", help="trusted Root CA (file stem)")
    parser.add_argument("--aa", default="aa", help="trusted AA (file stem)")
    parser.add_argument("--at", required=True, help="own AT (file stem; .cert and .pem)")
    parser.add_argument("--station-id", type=int, default=1)
    parser.add_argument("--lat", type=float, default=41.3870)
    parser.add_argument("--lon", type=float, default=2.1700)
    parser.add_argument("--no-cam", dest="cam", action="store_false")
    parser.add_argument("--denm-interval", type=int, default=1000, help="ms, 0 = no DENMs")
    args = parser.parse_args()

    trajectory, ca, den, link = build(args)
    stop = threading.Event()
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, lambda *_: stop.set())
    log(args.node, "start", stack="flexstack-python")
    trajectory.thread.start()
    if args.cam:
        ca.start()
    while not stop.wait(args.denm_interval / 1000 if args.denm_interval else 1.0):
        if args.denm_interval:
            lat, lon = trajectory.position
            position = {"latitude": int(lat * 1e7), "longitude": int(lon * 1e7),
                        "positionConfidenceEllipse": {"semiMajorConfidence": 4095,
                                                      "semiMinorConfidence": 4095,
                                                      "semiMajorOrientation": 3601},
                        "altitude": {"altitudeValue": 800001, "altitudeConfidence": "unavailable"}}
            result = den.trigger_denm(DENMRequest(
                position, situation={"informationQuality": 1, "eventType": {"ccAndScc": ("roadworks3", 0)}},
                location=LOCATION))
            log(args.node, "denm_tx", accepted=bool(result.ok))
    trajectory.stop.set()
    den.stop()
    log(args.node, "stop")
    link.sock.close()
    os._exit(0)  # pylint: disable=protected-access


if __name__ == "__main__":
    random.seed()
    main()
